"""Catch false passes for missing, duplicated, unrelated or stalled observations."""
from array import array
import math
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))
from tools.vrchat_audio_probe import compare_pcm, silence_pcm

RATE = 8000

def fixture():
    # Deliberately non-periodic envelope; not generated by the detector.
    samples = []
    for amplitude in [0, 500, 2500, 100, 1400, 0, 3200, 800, 0, 1800, 200, 0]:
        samples.extend(int(amplitude * math.sin(2 * math.pi * 220 * n / RATE)) for n in range(800))
    return array('h', samples).tobytes()


def test_accepts_one_scaled_replay_with_leading_and_trailing_silence():
    ref = fixture()
    scaled = array('h', (v // 3 for v in array('h', ref))).tobytes()
    result = compare_pcm(ref, b'\0' * 8000 + scaled + b'\0' * 16000, RATE)
    assert result.get('verdict') == 'pass'
    assert result.get('occurrences') == 1


def test_two_replays_fail_exactly_once():
    ref = fixture()
    result = compare_pcm(ref, ref + b'\0' * 8000 + ref, RATE)
    assert result.get('verdict') == 'fail'
    assert result.get('occurrences') == 2


def test_unrelated_constant_sound_is_not_speech_success():
    noise = array('h', (1000 if n % 2 else -1000 for n in range(24000))).tobytes()
    assert compare_pcm(fixture(), noise, RATE).get('verdict') == 'fail'


def test_missing_audio_is_inconclusive_not_silence():
    assert silence_pcm(b'', RATE, minimum_seconds=2).get('verdict') == 'inconclusive'
    assert compare_pcm(fixture(), b'', RATE).get('verdict') == 'inconclusive'


def test_short_or_partial_capture_does_not_pass():
    assert silence_pcm(b'\0' * 8000, RATE, minimum_seconds=2).get('verdict') == 'inconclusive'
    assert compare_pcm(fixture(), fixture()[:3200], RATE).get('verdict') == 'inconclusive'


def test_live_post_stop_silence_and_audio_are_distinguished():
    assert silence_pcm(b'\0' * 32000, RATE, minimum_seconds=2).get('verdict') == 'pass'
    assert silence_pcm(fixture() * 2, RATE, minimum_seconds=2).get('verdict') == 'fail'


def test_silent_reference_cannot_validate_silence_as_a_replay():
    assert compare_pcm(b'\0' * 16000, b'\0' * 32000, RATE).get('verdict') == 'inconclusive'


def test_malformed_pcm_is_not_accepted():
    assert silence_pcm(b'\0' * 32001, RATE, minimum_seconds=2).get('verdict') == 'inconclusive'


def test_matching_envelope_is_only_a_pattern_check_not_content_identity():
    # A different pitch with the same amplitude pattern can match: disclose the boundary.
    ref = fixture()
    different_pitch = []
    for amplitude in [0, 500, 2500, 100, 1400, 0, 3200, 800, 0, 1800, 200, 0]:
        different_pitch.extend(int(amplitude * math.sin(2 * math.pi * 440 * n / RATE)) for n in range(800))
    result = compare_pcm(ref, array('h', different_pitch).tobytes(), RATE)
    assert result.get('perceptual_quality_measured') is False


def test_late_audio_after_stop_fails_even_when_last_five_seconds_are_silent():
    # Full post-stop window, rather than just its tail, must be checked.
    pcm = b'\0' * 16000 + fixture() + b'\0' * 80000
    assert silence_pcm(pcm, RATE, minimum_seconds=5).get('verdict') == 'fail'
